import{_ as e,c as o,o as d,ag as a}from"./chunks/framework._xRlcm3f.js";const h=JSON.parse('{"title":"Quartz 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/github-quartz.md","filePath":"platforms/github-quartz.md","lastUpdated":1790228279000}'),r={name:"platforms/github-quartz.md"};function c(s,t,i,l,n,u){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="quartz-配置指南" tabindex="-1">Quartz 配置指南 <a class="header-anchor" href="#quartz-配置指南" aria-label="Permalink to &quot;Quartz 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Quartz</strong> 静态博客仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Quartz 博客仓库的 <strong>GitHub 仓库</strong>（如 <code>terwer/quartz-blog</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li><li>该仓库是一个标准 Quartz 项目（含 <code>content/</code> 内容目录与 <code>quartz.config.yaml</code>）。请勿使用上游 <code>jackyzha0/quartz</code> 仓库作为发布目标。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Quartz 博客仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>terwer/quartz-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Quartz 文章存储目录，默认 <code>content</code>。发布后的 <code>.md</code> 写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[filename].md</code></td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code></td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code></td></tr><tr><td>图床</td><td>Quartz 支持内置图床，选「当前平台」：图片上传到仓库 <code>assets/images</code>（默认），文章中引用为绝对路径 <code>/assets/images/&lt;图片名&gt;</code></td></tr></tbody></table><h2 id="三、图片与目录约定-quartz" tabindex="-1">三、图片与目录约定（Quartz） <a class="header-anchor" href="#三、图片与目录约定-quartz" aria-label="Permalink to &quot;三、图片与目录约定（Quartz）&quot;">​</a></h2><ul><li>Quartz 的文章来源目录是 <strong><code>content/</code></strong>，文章 <code>.md</code> 写入该目录，文件名默认 <code>[filename].md</code>（不带日期前缀）。</li><li>图片选「当前平台」图床时，会提交到仓库根目录的 <strong><code>assets/images/</code></strong>，文章内引用为 <strong>绝对路径 <code>/assets/images/&lt;图片名&gt;</code></strong>。</li><li>文章 front matter 常用的字段：<code>title</code>、<code>date</code>、<code>updated</code>、<code>description</code>、<code>tags</code>、<code>categories</code>、<code>permalink</code>（开启「YAML 永久链接」时写入，与「文章预览规则」一致）、<code>enableToc</code>、<code>enableBackLinks</code>。</li><li><strong>注意</strong>：图片最终能否在构建产物站点显示，取决于 Quartz 站点对 <code>/assets</code> 静态资源的处理方式（构建时能否把 <code>assets/images</code> 复制到输出根目录）。若引用为绝对 <code>/assets/images/...</code> 无法显示，需在 <code>quartz.config.yaml</code> 中把静态资源目录配置到内容目录下（如 <code>content/assets/images</code>）。Host 验证时会据此确认并记录。</li></ul><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过（会向仓库发布并清理测试文件）→ 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Quartz → 发布。文章 <code>.md</code> 会提交到 <code>存储目录/[filename].md</code>。</li><li>点「查看文章」能打开仓库中该 <code>.md</code> 的 blob 地址；带图发布时图片会一并上传到仓库 <code>assets/images</code> 并在文章中引用 <code>/assets/images/&lt;图片名&gt;</code>。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限，仓库名与分支正确，存储目录已存在。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：选「当前平台」图床，图片上传到仓库 <code>assets/images</code>，文章中引用绝对路径 <code>/assets/images/&lt;图片名&gt;</code>。具体能否显示取决于 Quartz 站点对 <code>/assets</code> 的处理。</li><li><strong>查看链接打不开</strong>：查看链接默认是仓库 blob 地址（<code>/[user]/[repo]/blob/[branch]/[docpath]</code>），仓库中存在该 <code>.md</code> 即可打开；若改为站点文章预览规则，需站点已部署且地址与规则一致。</li><li><strong>发布后线上没有新文章</strong>：Quartz 是通过构建（<code>npx quartz build</code>）从 <code>content/</code> 生成站点的，仅推送 <code>.md</code> 不会直接改变已部署站点；需配置自动构建（GitHub Actions / Pages / Vercel / Netlify 等）并触发一次构建。</li><li><strong>更新与删除</strong>：点「更新」会重新提交并产生一次新提交；「删除」会从仓库移除对应 <code>.md</code>，需重新构建才能从站点移除。</li></ul>',12)])])}const b=e(r,[["render",c]]);export{h as __pageData,b as default};
